const TINTS = [
  { name: "violet",   fg: "#9775fa", solid: "#7c5ce0" },
  { name: "info",     fg: "#60a5fa", solid: "#3b82f6" },
  { name: "success",  fg: "#34d399", solid: "#10b981" },
  { name: "warning",  fg: "#f59e0b", solid: "#d97706" },
  { name: "lavender", fg: "#c4b5fd", solid: "#9775fa" },
  { name: "neutral",  fg: "#babac1", solid: "#71717a" },
];

function fnv1a(id) {
  let h = 0x811c9dc5;
  for (let i = 0; i < id.length; i++) { h ^= id.charCodeAt(i); h = Math.imul(h, 0x01000193); }
  return h >>> 0;
}

const f = (n) => +n.toFixed(2);

/* Head: square left corners, round right corners (both from the logo), and a notch in the top
   edge whose slanted side is exactly 60 degrees, the angle of the logo's diagonal. Right corners
   are continuous-curvature cubics, not plain arcs, so the straight edges don't pinch. */
const TAN30 = 0.5774;
function head(x, y, w, h, round = false) {
  const rl = 1.4, rr = Math.min(5.5, h / 2 / 1.3), k = 1.3 * rr, c = 0.42 * rr;
  const nd = h * 0.3, nx = x + w * 0.34, nw = nd * TAN30;
  const R = x + w, B = y + h, hr = h / 2;
  if (round) // the right side is one half circle, like the round side of the logo
    return `M${f(x + rl)} ${f(y)}H${f(nx)}V${f(y + nd)}L${f(nx + nw)} ${f(y)}H${f(R - hr)}` +
      `A${f(hr)} ${f(hr)} 0 0 1 ${f(R - hr)} ${f(B)}` +
      `H${f(x + rl)}A${rl} ${rl} 0 0 1 ${f(x)} ${f(B - rl)}V${f(y + rl)}A${rl} ${rl} 0 0 1 ${f(x + rl)} ${f(y)}Z`;
  return `M${f(x + rl)} ${f(y)}H${f(nx)}V${f(y + nd)}L${f(nx + nw)} ${f(y)}H${f(R - k)}` +
    `C${f(R - c)} ${f(y)} ${f(R)} ${f(y + c)} ${f(R)} ${f(y + k)}V${f(B - k)}` +
    `C${f(R)} ${f(B - c)} ${f(R - c)} ${f(B)} ${f(R - k)} ${f(B)}` +
    `H${f(x + rl)}A${rl} ${rl} 0 0 1 ${f(x)} ${f(B - rl)}V${f(y + rl)}A${rl} ${rl} 0 0 1 ${f(x + rl)} ${f(y)}Z`;
}
const HEADS = [
  { name: "block", w: 18, h: 14 },
  { name: "tall",  w: 16, h: 16 },
  { name: "wide",  w: 20, h: 11 },
  { name: "round", w: 18, h: 15, round: true },
];

function circle(cx, cy, r) { return `M${f(cx - r)} ${f(cy)}a${r} ${r} 0 1 0 ${2 * r} 0a${r} ${r} 0 1 0 ${-2 * r} 0Z`; }
function rrect(x, y, w, h, r) {
  return `M${f(x + r)} ${f(y)}H${f(x + w - r)}A${r} ${r} 0 0 1 ${f(x + w)} ${f(y + r)}V${f(y + h - r)}A${r} ${r} 0 0 1 ${f(x + w - r)} ${f(y + h)}` +
    `H${f(x + r)}A${r} ${r} 0 0 1 ${f(x)} ${f(y + h - r)}V${f(y + r)}A${r} ${r} 0 0 1 ${f(x + r)} ${f(y)}Z`;
}
/* Every eye is at least 2.6 units across, so it stays an open hole at 16 px. */
const EYES = [
  { name: "dots",  draw: (l, r, cy) => circle(l, cy, 1.9) + circle(r, cy, 1.9) },
  { name: "tall",  draw: (l, r, cy) => rrect(l - 1.3, cy - 2.3, 2.6, 4.6, 1.3) + rrect(r - 1.3, cy - 2.3, 2.6, 4.6, 1.3) },
  { name: "calm",  draw: (l, r, cy) => [l, r].map(x => `M${f(x - 2.3)} ${f(cy - 1)}H${f(x + 2.3)}A2.3 2.3 0 0 1 ${f(x - 2.3)} ${f(cy - 1)}Z`).join("") },
  { name: "happy", draw: (l, r, cy) => [l, r].map(x => `M${f(x - 2.4)} ${f(cy + 1.1)}Q${f(x)} ${f(cy - 3.3)} ${f(x + 2.4)} ${f(cy + 1.1)}L${f(x + 1.1)} ${f(cy + 1.6)}Q${f(x)} ${f(cy - 0.9)} ${f(x - 1.1)} ${f(cy + 1.6)}Z`).join("") },
  { name: "wink",  draw: (l, r, cy) => circle(l, cy, 1.9) + `M${f(r - 2.4)} ${f(cy + 1.1)}Q${f(r)} ${f(cy - 3.3)} ${f(r + 2.4)} ${f(cy + 1.1)}L${f(r + 1.1)} ${f(cy + 1.6)}Q${f(r)} ${f(cy - 0.9)} ${f(r - 1.1)} ${f(cy + 1.6)}Z` },
  { name: "visor", draw: (l, r, cy) => rrect(l - 3.2, cy - 2.6, r - l + 6.4, 5.2, 2.6) + circle(l, cy, 1.4) + circle(r, cy, 1.4) },
];
/* Centre the whole face in the 24 x 24 box, then lift it 0.4 to the optical centre. */
function compose(headIdx, eyeIdx) {
  const { w, h, round } = HEADS[headIdx];
  const x = (24 - w) / 2, y = (24 - h) / 2 - 0.4;
  const cy = y + h * 0.56, l = x + w * 0.5 - w * 0.2, r = x + w * 0.5 + w * 0.2;
  return head(x, y, w, h, round) + EYES[eyeIdx].draw(l, r, cy);
}

/* No tops: an antenna on the head read as the letter "i". Variety comes from head, eyes and colour. */
function botFace(id) {
  let n = fnv1a(id);
  const tint = n % 6;  n = Math.floor(n / 6);                 // same colour the app already gives this id
  const headIdx = n % 4; n = Math.floor(n / 4);
  const eyeIdx = n % 6;
  return { d: compose(headIdx, eyeIdx), tint };
}

